// Implements Comparable — defines NATURAL ordering by tradeId
package com.bank.ordering.model;

import java.math.BigDecimal;

public class Trade implements Comparable<Trade> {

    private final String tradeId;
    private final String symbol;
    private final BigDecimal amount;
    private final String status;

    public Trade(String tradeId, String symbol, BigDecimal amount, String status) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.amount = amount;
        this.status = status;
    }

    // ═══ NATURAL ORDERING: by tradeId (chronological) ═══
    @Override
    public int compareTo(Trade other) {
        return this.tradeId.compareTo(other.tradeId);
    }
    // This is THE natural order. ONE per class. Used by sorted(), TreeSet, Collections.sort()

    public String getTradeId() { return tradeId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }

    @Override
    public String toString() {
        return tradeId + " " + symbol + " Rs." + amount + " [" + status + "]";
    }
}
