// ─── File: src/main/java/com/bank/ordering/service/TradeOrderingService.java ───
package com.bank.ordering.service;

import com.bank.ordering.dto.OrderingReport;
import com.bank.ordering.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class TradeOrderingService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-005", "WIPRO",    new BigDecimal("33664"),  "SETTLED"),
        new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-003", "HDFC",     new BigDecimal("330150"), "PENDING"),
        new Trade("TRD-002", "TCS",      new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-004", "INFY",     new BigDecimal("222037"), "FAILED")
    );

    // ═══ EXTERNAL COMPARATORS — defined OUTSIDE the Trade class ═══
    private static final Comparator<Trade> BY_AMOUNT_DESC =
        Comparator.comparing(Trade::getAmount).reversed();

    private static final Comparator<Trade> BY_SYMBOL_THEN_AMOUNT =
        Comparator.comparing(Trade::getSymbol)
            .thenComparing(Trade::getAmount, Comparator.reverseOrder());

    private static final Comparator<Trade> BY_STATUS_THEN_ID =
        Comparator.comparing(Trade::getStatus)
            .thenComparing(Comparator.naturalOrder());  // natural = compareTo = by tradeId

    public OrderingReport demonstrateOrdering() {
        Map<String, List<String>> results = new LinkedHashMap<>();

        // ═══ 1. NATURAL ORDER (Comparable.compareTo — by tradeId) ═══
        results.put("1_natural_compareTo", trades.stream()
            .sorted()  // uses Trade.compareTo → by tradeId
            .map(Trade::toString).toList());
        // TRD-001, TRD-002, TRD-003, TRD-004, TRD-005

        // ═══ 2. NATURAL ORDER via Comparator.naturalOrder() ═══
        results.put("2_naturalOrder_comparator", trades.stream()
            .sorted(Comparator.naturalOrder())  // same as sorted() — wraps compareTo
            .map(Trade::toString).toList());

        // ═══ 3. REVERSE of natural order ═══
        results.put("3_reverseOrder", trades.stream()
            .sorted(Comparator.reverseOrder())  // reverse of compareTo
            .map(Trade::toString).toList());
        // TRD-005, TRD-004, TRD-003, TRD-002, TRD-001

        // ═══ 4. EXTERNAL: by amount descending ═══
        results.put("4_external_amount_desc", trades.stream()
            .sorted(BY_AMOUNT_DESC)
            .map(Trade::toString).toList());
        // HDFC 330150, RELIANCE 245050, INFY 222037, TCS 176000, WIPRO 33664

        // ═══ 5. EXTERNAL: by symbol then amount ═══
        results.put("5_external_symbol_amount", trades.stream()
            .sorted(BY_SYMBOL_THEN_AMOUNT)
            .map(Trade::toString).toList());

        // ═══ 6. MIXED: status then NATURAL ORDER for tiebreak ═══
        results.put("6_status_then_natural", trades.stream()
            .sorted(BY_STATUS_THEN_ID)
            .map(Trade::toString).toList());
        // FAILED first (TRD-004), then PENDING (TRD-003), then SETTLED (by tradeId natural order)

        // ═══ 7. TreeSet uses natural order automatically ═══
        TreeSet<Trade> treeSet = new TreeSet<>(trades);
        results.put("7_treeSet_natural", treeSet.stream()
            .map(Trade::toString).toList());
        // TreeSet uses compareTo → TRD-001 through TRD-005

        return new OrderingReport(results);
    }
}
```

