// ─── File: src/test/java/com/bank/ordering/service/ComparableVsComparatorTest.java ───
package com.bank.ordering.service;

import com.bank.ordering.model.Trade;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ComparableVsComparatorTest {

    Trade t1 = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED");
    Trade t2 = new Trade("TRD-002", "TCS",      new BigDecimal("176000"), "SETTLED");
    Trade t3 = new Trade("TRD-003", "HDFC",     new BigDecimal("330150"), "PENDING");

    @Test
    void compareToDefinesNaturalOrder() {
        // Trade implements Comparable — compareTo by tradeId
        assertThat(t1.compareTo(t2)).isLessThan(0);   // TRD-001 < TRD-002
        assertThat(t2.compareTo(t1)).isGreaterThan(0); // TRD-002 > TRD-001
        assertThat(t1.compareTo(t1)).isEqualTo(0);     // equal to self
    }

    @Test
    void sortedUsesNaturalOrder() {
        List<Trade> sorted = List.of(t3, t1, t2).stream().sorted().toList();
        assertThat(sorted.get(0).getTradeId()).isEqualTo("TRD-001");
        assertThat(sorted.get(1).getTradeId()).isEqualTo("TRD-002");
        assertThat(sorted.get(2).getTradeId()).isEqualTo("TRD-003");
    }

    @Test
    void comparatorExternalDoesNotModifyClass() {
        Comparator<Trade> byAmount = Comparator.comparing(Trade::getAmount);
        List<Trade> sorted = List.of(t1, t2, t3).stream().sorted(byAmount).toList();
        assertThat(sorted.get(0).getTradeId()).isEqualTo("TRD-002");  // 176000 lowest
        assertThat(sorted.get(2).getTradeId()).isEqualTo("TRD-003");  // 330150 highest
    }

    @Test
    void naturalOrderWrapsCompareTo() {
        // Comparator.naturalOrder() delegates to compareTo
        Comparator<Trade> natural = Comparator.naturalOrder();
        assertThat(natural.compare(t1, t2)).isEqualTo(t1.compareTo(t2));
    }

    @Test
    void reverseOrderFlipsNatural() {
        Comparator<Trade> reversed = Comparator.reverseOrder();
        assertThat(reversed.compare(t1, t2)).isGreaterThan(0);  // TRD-001 > TRD-002 (reversed!)
    }

    @Test
    void treeSetUsesNaturalOrder() {
        TreeSet<Trade> set = new TreeSet<>(List.of(t3, t1, t2));
        assertThat(set.first().getTradeId()).isEqualTo("TRD-001");  // natural order
        assertThat(set.last().getTradeId()).isEqualTo("TRD-003");
    }

    @Test
    void treeSetWithComparator() {
        TreeSet<Trade> set = new TreeSet<>(Comparator.comparing(Trade::getAmount));
        set.addAll(List.of(t1, t2, t3));
        assertThat(set.first().getTradeId()).isEqualTo("TRD-002");  // lowest amount
        assertThat(set.last().getTradeId()).isEqualTo("TRD-003");   // highest amount
    }

    @Test
    void naturalOrderUsedInNullsLastWrapper() {
        // nullsLast needs a Comparator — naturalOrder() provides one from Comparable
        Comparator<String> nullSafe = Comparator.nullsLast(Comparator.naturalOrder());
        List<String> sorted = new ArrayList<>(List.of("B", null, "A"));
        sorted.sort(nullSafe);
        assertThat(sorted).containsExactly("A", "B", null);  // null last!
    }
}
